import{G as e,K as t,at as n,n as r}from"./chunks/framework.Cv3A6T7g.js";var i=JSON.parse(`{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"config/api/index.md","filePath":"config/api/index.md"}`),a={name:`config/api/index.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h1><p>Configuration files are stored in <code>src/config</code> directory of <code>application</code> or <code>package</code>.</p><p>Configuration is structured to following sections:</p><ul><li><a href="/config/api/application">Application</a></li><li><a href="/config/api/acl">Access Control List (ACL)</a></li><li><a href="/config/api/cache">Cache</a></li><li><a href="/config/api/database">Database</a></li><li><a href="/config/api/filesystem">Filesystem</a></li><li><a href="/config/api/images">Image processing</a></li><li><a href="/config/api/log">Logging</a></li><li><a href="/config/api/mail">Mail</a></li><li><a href="/config/api/media">Media</a></li><li><a href="/config/api/metrics">Metrics</a></li><li><a href="/config/api/package-io">Package import / export</a></li><li><a href="/config/api/pdf">PDF generation</a></li><li><a href="/config/api/pub-sub">Pub-sub</a></li><li><a href="/config/api/queue">Queue</a></li><li><a href="/config/api/rate-limiter">Rate limiter</a></li><li><a href="/config/api/security">Security</a></li><li><a href="/config/api/services">Services</a></li><li><a href="/config/api/session">Session</a></li></ul><h2 id="redis" tabindex="-1">Redis <a class="header-anchor" href="#redis" aria-label="Permalink to “Redis”">​</a></h2><p><a href="https://redis.io" target="_blank" rel="noreferrer">Redis</a> is used by several parts of the system (<a href="/config/api/cache">cache</a>, <a href="/config/api/pub-sub">pub-sub</a>, <a href="/config/api/queue">queue</a>, <a href="/config/api/rate-limiter">rate limiter</a>, <a href="/config/api/session">session</a>). Each of them has its own <code>{SECTION}_REDIS_*</code> connection settings, so they can be configured independently if needed.</p><p>Common connection settings below are used as a fallback for any section, which does not define its own <code>{SECTION}_REDIS_*</code> variable.</p><h3 id="url" tabindex="-1">URL <a class="header-anchor" href="#url" aria-label="Permalink to “URL”">​</a></h3><p>Connection URL, e.g. <code>redis://localhost:6379/0</code>. Takes precedence over host / port / database settings.</p><ul><li>dotenv var: <code>REDIS_URL</code></li><li>type: <code>string</code></li><li>default: <code>undefined</code></li></ul><h3 id="host" tabindex="-1">Host <a class="header-anchor" href="#host" aria-label="Permalink to “Host”">​</a></h3><ul><li>dotenv var: <code>REDIS_HOST</code></li><li>type: <code>string</code></li><li>default: <code>&#39;localhost&#39;</code></li></ul><h3 id="port" tabindex="-1">Port <a class="header-anchor" href="#port" aria-label="Permalink to “Port”">​</a></h3><ul><li>dotenv var: <code>REDIS_PORT</code></li><li>type: <code>number</code></li><li>default: <code>6379</code></li></ul><h3 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to “Database”">​</a></h3><ul><li>dotenv var: <code>REDIS_DATABASE</code></li><li>type: <code>number</code></li><li>default: <code>0</code></li></ul>`,16)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};